class DataPipeline:
    def __init__(self):
        self._steps = []
        self._errors = []

    def add_step(self, name, func):
        self._steps.append((name, func))

    def run(self, data):
        result = data
        for name, func in self._steps:
            try:
                result = func(result)
            except Exception as e:
                self._errors.append((name, str(e)))
                return None
        return result

    def get_errors(self):
        return list(self._errors)

    def reset(self):
        self._steps = []
        self._errors = []

